// AdStreamX iframe player page.
// URL forms:
//   /embed/#cfg=<base64url EmbedConfig>   full config (generated by generateEmbedCode)
//   /embed/?src=<url>                      quick preview of one source (no remote control)
// The fragment is never sent to the server, so player config does not end up in access logs.
import { AdStreamX, createEd25519Verifier } from '@adstreamx/player-sdk';
import { decodeEmbedConfig, EmbedServer, type EmbedConfig } from '@adstreamx/embed-protocol';

function readConfig(): { ok: true; config: EmbedConfig } | { ok: false; error: string } {
  const hash = new URLSearchParams(location.hash.slice(1));
  const cfg = hash.get('cfg');
  if (cfg) return decodeEmbedConfig(cfg);
  const src = new URLSearchParams(location.search).get('src');
  if (src) return { ok: true, config: { player: { source: { src } }, allowedOrigins: [] } };
  return { ok: false, error: 'No player configuration was provided.' };
}

function showError(message: string): void {
  const box = document.createElement('div');
  box.className = 'embed-error';
  box.setAttribute('role', 'alert');
  box.textContent = message; // text only
  document.body.appendChild(box);
}

const parsed = readConfig();
if (!parsed.ok) {
  showError(`This player could not start: ${parsed.error}`);
} else {
  const { config } = parsed;
  const root = document.getElementById('player')!;
  try {
    const player = AdStreamX.create(root, config.player, {
      commandVerifier: config.operatorKeys ? createEd25519Verifier(config.operatorKeys) : undefined,
    });
    const server = window.parent !== window
      ? new EmbedServer({
          player: {
            getState: () => player.getState(),
            getCapabilities: () => player.getCapabilities(),
            on: (event, fn) => player.on(event as 'play', fn as () => void),
            command: (cmd, role) => player.command(cmd, role),
          },
          allowedOrigins: config.allowedOrigins,
          channel: config.channel ?? 'default',
          target: window.parent,
          self: window,
          version: AdStreamX.VERSION,
        })
      : null;
    // Exposed for diagnostics in the browser console of the embed page only.
    (window as unknown as { __adstreamxEmbed: unknown }).__adstreamxEmbed = { player, server };
    window.addEventListener('pagehide', () => {
      server?.destroy();
      player.destroy();
    });
  } catch (e) {
    showError(`This player could not start: ${(e as Error).message}`);
  }
}
